class Solution(object):
    def constructDistancedSequence(self, n):
        """
        :type n: int
        :rtype: List[int]
        """
        self.ans = None
        self.dfs([0 for _ in range(2 * n - 1)], [0 for _ in range(n)], 0, n)
        return self.ans

    def dfs(self, cur_ans, cur_vis, cur_pos, n):
        if self.ans:
            return
        if cur_pos == 2 * n - 1:
            self.ans = cur_ans[:]
            return
        if cur_ans[cur_pos] != 0:
            self.dfs(cur_ans, cur_vis, cur_pos + 1, n)
        else:
            for new_num in range(n, -1, -1):
                if cur_vis[new_num - 1]:
                    continue
                if cur_pos + new_num >= 2 * n - 1:
                    break
                if cur_ans[cur_pos + new_num] != 0:
                    continue
                new_ans = cur_ans[:]
                new_vis = cur_vis[:]
                new_ans[cur_pos] = new_num
                new_ans[cur_pos + new_num] = new_num
                new_vis[new_num - 1] = 1
                self.dfs(new_ans, new_vis, cur_pos + 1, n)
            if cur_vis[0] == 0:
                new_ans = cur_ans[:]
                new_vis = cur_vis[:]
                new_ans[cur_pos] = 1
                new_vis[0] = 1
                self.dfs(new_ans, new_vis, cur_pos + 1, n)

class Solution:
    def checkWays(self, pairs):
        info = collections.defaultdict(set)
        for x, y in pairs:
            info[x].add(y)
            info[y].add(x)

        n = len(info)
        ind = -1
        for k, v in info.items():
            if len(v) == n - 1:
                ind = k
                break
        if ind == -1:
            return 0

        ans = 1
        for node, neighbours in info.items():
            if node == ind:
                continue
            cur_degree = len(neighbours)
            cur_parent = -1
            cur_parent_degree = float("inf")
            for neighbour in neighbours:
                if cur_degree <= len(info[neighbour]) < cur_parent_degree:
                    cur_parent = neighbour
                    cur_parent_degree = len(info[neighbour])
            if cur_parent == 0:
                return 0
            for neighbour in neighbours:
                if neighbour == cur_parent:
                    continue
                if neighbour not in info[cur_parent]:
                    return 0
            if cur_parent_degree == cur_degree:
                ans = 2
        return ans
